import PDFDocument from 'pdfkit';
import fs from 'fs';

const doc = new PDFDocument({ 
  size: 'A4', 
  margins: { top: 50, bottom: 50, left: 50, right: 50 },
  bufferPages: true
});

const output = fs.createWriteStream('PMG-OS-Testing-Checklist.pdf');
doc.pipe(output);

const CRIMSON = '#DC2626';
const NAVY = '#0F172A';
const DARK_GRAY = '#374151';
const MED_GRAY = '#6B7280';
const LIGHT_GRAY = '#E5E7EB';

function addHeader() {
  doc.rect(0, 0, doc.page.width, 120).fill(NAVY);
  doc.fontSize(28).fill('#FFFFFF').font('Helvetica-Bold').text('PMG GROUP OS', 50, 30, { align: 'center' });
  doc.fontSize(14).fill('#F87171').font('Helvetica').text('Complete Testing & Verification Checklist', { align: 'center' });
  doc.fontSize(9).fill('#94A3B8').text('Based on: PMG OS Blueprint v2 + v3 | 32 Agents | 6 Sections | 3 AI Modes | 75+ Detailed Test Items', { align: 'center' });
  doc.moveDown(2);
}

function addSectionDivider() {
  const y = doc.y;
  doc.moveTo(50, y).lineTo(doc.page.width - 50, y).lineWidth(0.5).strokeColor(LIGHT_GRAY).stroke();
  doc.moveDown(0.5);
}

function checkSpace(needed) {
  if (doc.y + needed > doc.page.height - 60) {
    doc.addPage();
  }
}

function writeHeading(text, level) {
  if (level === 1) {
    checkSpace(60);
    doc.moveDown(0.5);
    const y = doc.y;
    doc.rect(50, y, doc.page.width - 100, 30).fill(CRIMSON);
    doc.fontSize(14).fill('#FFFFFF').font('Helvetica-Bold').text(text, 60, y + 8);
    doc.y = y + 40;
    doc.moveDown(0.3);
  } else if (level === 2) {
    checkSpace(40);
    doc.moveDown(0.3);
    doc.fontSize(12).fill(NAVY).font('Helvetica-Bold').text(text);
    addSectionDivider();
  } else {
    checkSpace(30);
    doc.fontSize(10).fill(CRIMSON).font('Helvetica-Bold').text(text);
    doc.moveDown(0.2);
  }
}

function writeParagraph(label, text) {
  checkSpace(40);
  doc.fontSize(9).fill(CRIMSON).font('Helvetica-Bold').text(label, { continued: false });
  doc.fontSize(9).fill(DARK_GRAY).font('Helvetica').text(text);
  doc.moveDown(0.3);
}

function writeStatusLine() {
  checkSpace(30);
  doc.moveDown(0.3);
  doc.fontSize(9).fill(NAVY).font('Helvetica-Bold').text('YOUR STATUS (circle one):     ', { continued: true });
  doc.fill(CRIMSON).text('PASS', { continued: true });
  doc.fill(DARK_GRAY).text('     /     ', { continued: true });
  doc.fill('#D97706').text('PARTIAL', { continued: true });
  doc.fill(DARK_GRAY).text('     /     ', { continued: true });
  doc.fill('#DC2626').text('FAIL', { continued: true });
  doc.fill(DARK_GRAY).text('     /     ', { continued: true });
  doc.fill(MED_GRAY).text('N/A');
  doc.moveDown(0.3);
}

function writeNotesLine() {
  doc.fontSize(9).fill(NAVY).font('Helvetica-Bold').text('YOUR NOTES:');
  doc.moveDown(0.1);
  for (let i = 0; i < 3; i++) {
    const y = doc.y;
    doc.moveTo(50, y).lineTo(doc.page.width - 50, y).lineWidth(0.3).strokeColor(LIGHT_GRAY).stroke();
    doc.moveDown(0.8);
  }
  doc.moveDown(0.5);
  const divY = doc.y;
  doc.moveTo(50, divY).lineTo(doc.page.width - 50, divY).lineWidth(1).strokeColor(NAVY).stroke();
  doc.moveDown(1);
}

function writeTestItem(number, title, howItWorks, aiAuto, hybrid, human, expected) {
  checkSpace(200);
  doc.fontSize(11).fill(NAVY).font('Helvetica-Bold').text(`${number} — ${title}`);
  doc.moveDown(0.3);
  writeParagraph('HOW IT WORKS:', howItWorks);
  writeParagraph('IN AI AUTONOMOUS MODE:', aiAuto);
  writeParagraph('IN HYBRID MODE:', hybrid);
  writeParagraph('IN HUMAN CONTROLLED MODE:', human);
  writeParagraph('EXPECTED RESULT:', expected);
  writeStatusLine();
  writeNotesLine();
}

