for (const section of testItems) {
  writeHeading(section.section, 1);
  doc.fontSize(9).fill(DARK_GRAY).font('Helvetica').text(section.sectionDesc);
  doc.moveDown(0.8);
  
  for (const item of section.items) {
    writeTestItem(item.num, item.title, item.how, item.ai, item.hybrid, item.human, item.expected);
  }
}

